"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6048],{4634:e=>{e.exports=JSON.parse('{"functions":[{"name":"FinallyTask","desc":"Spawns `callback` via `taskExec` (typically `task.spawn` or\\n`task.defer`), passing it a fresh cleanup scope followed by the extra\\narguments. The callback registers its cleanup tasks into that scope; if\\nit errors, the scope is passed to `doCleanup` before the error\\npropagates.\\n\\n```lua\\nlocal stop = FinallyTask(task.spawn, function(scope)\\n\\ttable.insert(scope, workspace.ChildAdded:Connect(print))\\n\\twhile true do task.wait(1) end\\nend)\\n-- later: cancels the thread and runs the scope\'s cleanup\\nstop()\\n```","params":[{"name":"taskExec","desc":"Scheduler used to start the callback, e.g. `task.spawn`.","lua_type":"(callback, scope, Args...) -> thread"},{"name":"callback","desc":"Work to run; receives the cleanup scope first.","lua_type":"(scope: { unknown }, Args...) -> ()"},{"name":"...","desc":"Extra arguments forwarded to the callback.","lua_type":"Args..."}],"returns":[{"desc":"Destructor: cancels the thread (if still running) and cleans up the scope. Safe to call more than once.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":39,"path":"plugin/finally-task/init.luau"}}],"properties":[],"types":[],"name":"FinallyTask","desc":"Runs a callback on a new thread and guarantees its cleanup scope is torn\\ndown exactly once, whether the callback errors, is cancelled from\\noutside, or the returned destructor is called.","source":{"line":14,"path":"plugin/finally-task/init.luau"}}')}}]);